/**
 * Static-index retrieval chain, ported from the Python production code.
 *
 * Every function here mirrors one Python function and is pinned to it by
 * golden vectors in golden_retrieval.json (generated by
 * scripts/make_golden_retrieval_vectors.py from the real index):
 *
 *   arcLengthResample  == earthglyph.geometry.resampling.arc_length_resample
 *   smoothCyclic       == earthglyph.geometry.sketch.smooth_cyclic
 *   normalizeContour   == earthglyph.geometry.normalization.normalize_contour
 *   harmonicAmplitudes == earthglyph.features.fourier.harmonic_amplitudes
 *   shapeMetrics       == earthglyph.features.geometry_stats.shape_metrics
 *   coarseShortlist    == earthglyph.retrieval.coarse.rank (group=fourier)
 *
 * The ports keep the Python operation order where it is observable (summation
 * order, fftfreq construction, stable tie-breaking) so the tolerances in the
 * golden file stay at 1e-9. DFT/smoothing use a direct O(N^2) DFT — N is 128,
 * so per-query cost is ~16k complex operations, negligible next to the 839x16
 * distance sweep.
 */

export type Point = readonly [x: number, y: number];

export class ChainError extends Error {}

/** Ensure the ring walks counter-clockwise (positive signed area). */
export function ensureCcw(points: readonly Point[]): Point[] {
  let area2 = 0;
  for (let i = 0; i < points.length; i++) {
    const [x0, y0] = points[i];
    const [x1, y1] = points[(i + 1) % points.length];
    area2 += x0 * y1 - x1 * y0;
  }
  if (area2 >= 0) return [...points];
  return [...points].reverse();
}

/**
 * Resample an open ring to n points equally spaced by cumulative arc length.
 * First sample sits on the first vertex (Python contract).
 */
export function arcLengthResample(ringOpen: readonly Point[], n: number): Point[] {
  if (n < 3) throw new ChainError(`n must be at least 3, got ${n}`);
  const closed: Point[] = [...ringOpen, ringOpen[0]];
  const m = closed.length;
  const cumulative = new Float64Array(m);
  for (let i = 1; i < m; i++) {
    const dx = closed[i][0] - closed[i - 1][0];
    const dy = closed[i][1] - closed[i - 1][1];
    cumulative[i] = cumulative[i - 1] + Math.hypot(dx, dy);
  }
  const total = cumulative[m - 1];
  if (!Number.isFinite(total) || total <= 0) {
    throw new ChainError("ring has zero perimeter");
  }
  const step = total / n;
  const out: Point[] = [];
  let segment = 0; // cumulative[segment] <= target <= cumulative[segment+1]
  for (let k = 0; k < n; k++) {
    const target = k * step;
    while (segment < m - 2 && cumulative[segment + 1] < target) segment++;
    const span = cumulative[segment + 1] - cumulative[segment];
    const t = span > 0 ? (target - cumulative[segment]) / span : 0;
    const [x0, y0] = closed[segment];
    const [x1, y1] = closed[segment + 1];
    out.push([x0 + (x1 - x0) * t, y0 + (y1 - y0) * t]);
  }
  return out;
}

/**
 * Cyclic Gaussian low-pass of an arc-length-uniform closed contour, via the
 * frequency response exp(-2 (pi sigma f)^2) at fftfreq(n) (zero-phase, linear).
 * O(N^2) direct DFT; sigma = 0 returns the input.
 */
export function smoothCyclic(points: readonly Point[], sigma: number): Point[] {
  if (sigma <= 0) return [...points];
  const n = points.length;
  // z = x + i y; F[k] = sum_i z[i] * exp(-2 pi i k i / n)
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let k = 0; k < n; k++) {
    let sumRe = 0;
    let sumIm = 0;
    for (let i = 0; i < n; i++) {
      const angle = (-2 * Math.PI * k * i) / n;
      const c = Math.cos(angle);
      const s = Math.sin(angle);
      // z[i] * (c + i s) = (x c - y s) + i (x s + y c)
      sumRe += points[i][0] * c - points[i][1] * s;
      sumIm += points[i][0] * s + points[i][1] * c;
    }
    re[k] = sumRe;
    im[k] = sumIm;
  }
  const out: Point[] = new Array(n);
  for (let i = 0; i < n; i++) {
    let sumRe = 0;
    let sumIm = 0;
    for (let k = 0; k < n; k++) {
      // np.fft.fftfreq(n)[k] = k/n for k < n/2 else (k-n)/n; sigma only enters
      // squared, so the sign of the frequency is irrelevant here
      const f = k <= n / 2 ? k / n : (k - n) / n;
      const response = Math.exp(-2 * (Math.PI * sigma * f) ** 2);
      const angle = (2 * Math.PI * k * i) / n;
      const c = Math.cos(angle);
      const s = Math.sin(angle);
      // F[k] * response * (c + i s) then / n (numpy's ifft includes 1/n)
      const fr = re[k] * response;
      const fi = im[k] * response;
      sumRe += fr * c - fi * s;
      sumIm += fr * s + fi * c;
    }
    out[i] = [sumRe / n, sumIm / n];
  }
  return out;
}

/** Translate to the centroid and scale to unit RMS radius. */
export function normalizeContour(points: readonly Point[]): Point[] {
  if (points.length < 3) {
    throw new ChainError("a contour needs at least 3 points");
  }
  const n = points.length;
  let cx = 0;
  let cy = 0;
  for (const [x, y] of points) {
    cx += x;
    cy += y;
  }
  cx /= n;
  cy /= n;
  let sumSq = 0;
  for (const [x, y] of points) {
    sumSq += (x - cx) ** 2 + (y - cy) ** 2;
  }
  const rms = Math.sqrt(sumSq / n);
  if (rms <= 1e-12) {
    throw new ChainError("degenerate contour: zero RMS radius");
  }
  return points.map(([x, y]) => [(x - cx) / rms, (y - cy) / rms] as Point);
}

/**
 * Low-harmonic amplitude descriptor: |Z_k| / N for k = 1..nHarmonics of the
 * RMS-normalized contour (DC dropped). O(N * nHarmonics) direct DFT.
 */
export function harmonicAmplitudes(
  points: readonly Point[],
  nHarmonics: number,
): number[] {
  const n = points.length;
  if (nHarmonics < 1) throw new ChainError("n_harmonics must be >= 1");
  if (nHarmonics > n / 2 - 1) {
    throw new ChainError(`n_harmonics=${nHarmonics} exceeds the Nyquist limit`);
  }
  const normalized = normalizeContour(points);
  const out: number[] = [];
  for (let k = 1; k <= nHarmonics; k++) {
    let sumRe = 0;
    let sumIm = 0;
    for (let i = 0; i < n; i++) {
      const angle = (-2 * Math.PI * k * i) / n;
      sumRe += normalized[i][0] * Math.cos(angle) - normalized[i][1] * Math.sin(angle);
      sumIm += normalized[i][0] * Math.sin(angle) + normalized[i][1] * Math.cos(angle);
    }
    out.push(Math.hypot(sumRe, sumIm) / n);
  }
  return out;
}

function signedArea(points: readonly Point[]): number {
  let area2 = 0;
  for (let i = 0; i < points.length; i++) {
    const [x0, y0] = points[i];
    const [x1, y1] = points[(i + 1) % points.length];
    area2 += x0 * y1 - x1 * y0;
  }
  return area2 / 2;
}

function ringPerimeter(points: readonly Point[]): number {
  let length = 0;
  for (let i = 0; i < points.length; i++) {
    const [x0, y0] = points[i];
    const [x1, y1] = points[(i + 1) % points.length];
    length += Math.hypot(x1 - x0, y1 - y0);
  }
  return length;
}

/** Andrew's monotone chain, closing vertex omitted, collinear dropped. */
export function convexHullPoints(points: readonly Point[]): Point[] {
  const unique = Array.from(
    new Map(points.map((p) => [`${p[0]},${p[1]}`, p] as const)).values(),
  ).sort((a, b) => (a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]));
  if (unique.length < 3) {
    throw new ChainError(`fewer than 3 distinct points to hull (${unique.length})`);
  }
  const cross = (
    o: Point,
    a: Point,
    b: Point,
  ): number => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const build = (list: readonly Point[]): Point[] => {
    const stack: Point[] = [];
    for (const point of list) {
      while (
        stack.length >= 2 &&
        cross(stack[stack.length - 2], stack[stack.length - 1], point) <= 0
      ) {
        stack.pop();
      }
      stack.push(point);
    }
    return stack;
  };
  const lower = build(unique);
  const upper = build([...unique].reverse());
  const hull = [...lower.slice(0, -1), ...upper.slice(0, -1)];
  if (hull.length < 3) {
    throw new ChainError("point set is collinear: no convex hull area");
  }
  return hull;
}

/** Minimum-area enclosing rectangle extents (long, short) over hull edges. */
export function rotatedRectangleExtents(
  points: readonly Point[],
): [number, number] {
  const hull = convexHullPoints(points);
  let best: [number, number] | null = null;
  for (let i = 0; i < hull.length; i++) {
    const edgeX = hull[(i + 1) % hull.length][0] - hull[i][0];
    const edgeY = hull[(i + 1) % hull.length][1] - hull[i][1];
    const length = Math.hypot(edgeX, edgeY);
    if (length <= 0) continue;
    const ux = edgeX / length;
    const uy = edgeY / length;
    let minAlong = Infinity;
    let maxAlong = -Infinity;
    let minAcross = Infinity;
    let maxAcross = -Infinity;
    for (const [x, y] of hull) {
      const along = x * ux + y * uy;
      const across = -x * uy + y * ux;
      if (along < minAlong) minAlong = along;
      if (along > maxAlong) maxAlong = along;
      if (across < minAcross) minAcross = across;
      if (across > maxAcross) maxAcross = across;
    }
    const extents: [number, number] = [maxAlong - minAlong, maxAcross - minAcross];
    if (best === null || extents[0] * extents[1] < best[0] * best[1]) {
      best = extents;
    }
  }
  if (best === null) throw new ChainError("convex hull has no edges");
  return [Math.max(...best), Math.min(...best)];
}

/** The four geometry statistics, same degeneracy rules as Python. */
export function shapeMetrics(points: readonly Point[]): {
  compactness: number;
  solidity: number;
  aspectRatio: number;
  diameterFill: number;
} {
  const area = Math.abs(signedArea(points));
  const perimeter = ringPerimeter(points);
  if (area <= 0 || perimeter <= 0) {
    throw new ChainError("degenerate ring: zero area or zero perimeter");
  }
  const hullArea = Math.abs(signedArea(convexHullPoints(points)));
  if (hullArea <= 0) {
    throw new ChainError("degenerate ring: convex hull has no area");
  }
  let diameter = 0;
  for (let i = 0; i < points.length; i++) {
    for (let j = i + 1; j < points.length; j++) {
      const d = Math.hypot(points[j][0] - points[i][0], points[j][1] - points[i][1]);
      if (d > diameter) diameter = d;
    }
  }
  if (diameter <= 0) throw new ChainError("degenerate ring: zero diameter");
  const [longSide, shortSide] = rotatedRectangleExtents(points);
  if (shortSide <= 0) {
    throw new ChainError("degenerate ring: rotated rectangle has no width");
  }
  return {
    compactness: (4 * Math.PI * area) / perimeter ** 2,
    solidity: area / hullArea,
    aspectRatio: longSide / shortSide,
    diameterFill: (4 * area) / (Math.PI * diameter ** 2),
  };
}

/** Query feature vector [fourier(16) | geometry(4)] of a standardized contour. */
export function queryFeatureVector(
  normalized: readonly Point[],
  nHarmonics: number,
): number[] {
  const fourier = harmonicAmplitudes(normalized, nHarmonics);
  const geometry = shapeMetrics(normalized);
  return [
    ...fourier,
    geometry.compactness,
    geometry.solidity,
    geometry.aspectRatio,
    geometry.diameterFill,
  ];
}

export interface CoarseHit {
  row: number;
  distance: number;
}

/**
 * Coarse shortlist over the fourier group: per-column RMS distance
 * sqrt(mean(((lib - query))^2)) with a stable argsort (ties by row index).
 * Mirrors earthglyph.retrieval.coarse.rank(group="fourier", scale="none").
 */
export function coarseShortlist(
  queryFourier: readonly number[],
  libraryFourier: readonly number[][],
  size: number,
): CoarseHit[] {
  const n = libraryFourier.length;
  if (n === 0) throw new ChainError("library is empty");
  const width = libraryFourier[0].length;
  if (queryFourier.length !== width) {
    throw new ChainError(
      `query has ${queryFourier.length} features, library has ${width}`,
    );
  }
  const rows: { row: number; distance: number }[] = [];
  for (let r = 0; r < n; r++) {
    let sumSq = 0;
    for (let c = 0; c < width; c++) {
      const diff = libraryFourier[r][c] - queryFourier[c];
      sumSq += diff * diff;
    }
    rows.push({ row: r, distance: Math.sqrt(sumSq / width) });
  }
  rows.sort((a, b) =>
    a.distance !== b.distance ? a.distance - b.distance : a.row - b.row,
  );
  return rows.slice(0, size);
}
